<?php
declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/csrf.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/batches.php';$current=tuman_require_role('TEACHER');$db=tuman_database();$id=filter_var($_GET['id']??$_POST['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id||!($batch=tuman_teacher_batch($db,$current['id'],(int)$id))){http_response_code(404);exit('Batch unavailable.');}$rules=array_filter(tuman_batch_billing_rules($db,$current['id'],(int)$id),fn($rule)=>$rule['status']==='ACTIVE');$members=array_filter(tuman_batch_members($db,$current['id'],(int)$id),fn($member)=>$member['status']==='ACTIVE'&&$member['assignment_status']==='ACTIVE');$v=['billing_month'=>gmdate('Y-m'),'invoice_date'=>gmdate('Y-m-d'),'due_date'=>''];$choices=[];$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){foreach($v as $k=>$x)$v[$k]=trim((string)($_POST[$k]??''));$choices=is_array($_POST['member_rule']??null)?$_POST['member_rule']:[];try{if(!tuman_csrf_is_valid($_POST['csrf_token']??null))throw new InvalidArgumentException('Your request could not be verified.');$count=tuman_generate_batch_invoices_for_members($db,$current['id'],(int)$id,$v+['member_rule'=>$choices]);header('Location: /Tuman/teacher/invoices.php?batch_created='.$count);exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log($e->getMessage());$error='Unable to generate batch invoices right now.';}}tuman_teacher_page_start('Generate batch draft invoices');
?>
<style>.content form p:last-child:has(> button) { display:block; padding-left:0; text-align:left; }</style>
<h1>Generate batch draft invoices</h1><p><?=htmlspecialchars($batch['batch_name'],ENT_QUOTES,'UTF-8')?>. Choose the billing rule to apply to each student. Leave a student unselected to skip that student. Attendance is not used for this billing.</p><?php if($error):?><p role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php endif;?><?php if($rules===[]||$members===[]):?><p><?= $rules===[]?'Add a billing option before generating invoices.':'This batch has no active students.' ?></p><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(tuman_csrf_token(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="id" value="<?=(int)$id?>"><h2>Invoice details</h2><p><label>Billing month <input type="month" name="billing_month" required value="<?=htmlspecialchars($v['billing_month'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Invoice date <input type="date" name="invoice_date" required value="<?=htmlspecialchars($v['invoice_date'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Due date <input type="date" name="due_date" value="<?=htmlspecialchars($v['due_date'],ENT_QUOTES,'UTF-8')?>"></label></p><h2>Students and billing rules</h2><div style="overflow-x:auto"><table><thead><tr><th>Student</th><th>Email</th><th>Billing rule to apply</th></tr></thead><tbody><?php foreach($members as $member):?><tr><td><?=htmlspecialchars(trim($member['first_name'].' '.($member['last_name']??'')),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($member['email']??'',ENT_QUOTES,'UTF-8')?></td><td><select name="member_rule[<?=(int)$member['teacher_student_id']?>]"><option value="">Do not generate</option><?php foreach($rules as $rule):?><option value="<?=(int)$rule['id']?>"<?=($choices[(string)$member['teacher_student_id']]??'')==$rule['id']?' selected':''?>><?=htmlspecialchars($rule['rule_code'].' — '.$rule['rule_name'].' — '.tuman_currency_amount_label($rule['charge'],$rule['currency_code']),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></td></tr><?php endforeach;?></tbody></table></div><p><button>Generate selected draft invoices</button> <a href="/Tuman/teacher/batch-view.php?id=<?=(int)$id?>">Cancel</a></p></form><?php endif;tuman_teacher_page_end(); ?>
